draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = Math.atan2(p.a, p.g);
var geff = Math.sqrt(p.a * p.a + p.g * p.g);
var cx = W * 0.42, cy = H * 0.16;
var L = H * 0.44;
var bx = cx + L * Math.sin(th), by = cy + L * Math.cos(th);

// cart body
var cw = W * 0.52, chh = H * 0.62;
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.strokeRect(cx - cw / 2, cy - 10, cw, chh);
// wheels
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(cx - cw / 4, cy - 10 + chh + 8, 8, 0, 6.2832); ctx.fill();
ctx.beginPath(); ctx.arc(cx + cw / 4, cy - 10 + chh + 8, 8, 0, 6.2832); ctx.fill();
// ground
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(10, cy - 10 + chh + 16); ctx.lineTo(W - 10, cy - 10 + chh + 16); ctx.stroke();

// true vertical reference
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy + L + 24); ctx.stroke();
ctx.setLineDash([]);

// string and bob
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 9, 0, 6.2832); ctx.fill();

// angle arc
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, 34, Math.PI / 2 - th, Math.PI / 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("theta", cx + 16, cy + 46);

// force arrows from the bob (frame of the cart)
var S = H * 0.020;
function arrow(x0, y0, dx, dy, col, lab) {
  var x1 = x0 + dx, y1 = y0 + dy;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var an = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(an - 0.4), y1 - 8 * Math.sin(an - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(an + 0.4), y1 - 8 * Math.sin(an + 0.4));
  ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(lab, x1 + (dx < 0 ? -34 : 6), y1 + (dy > 0 ? 12 : -4));
}
arrow(bx, by, 0, p.g * S, C.figure, "mg");
arrow(bx, by, -p.a * S, 0, C.accent, "ma (pseudo)");
arrow(bx, by, -p.a * S, p.g * S, C.ink, "m g_eff");

// acceleration of the cart
ctx.fillStyle = C.ink;
arrow(cx + cw / 2 - 40, cy - 24, 40, 0, C.accent, "");
ctx.fillText("cart acceleration a", cx + cw / 2 - 150, cy - 28);

out.note = "theta = " + (th * 180 / Math.PI).toFixed(2) + " deg, g_eff = " + geff.toFixed(3) + " m/s^2";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var th = p.angle * Math.PI / 180;
var baseY = H * 0.80, x0 = W * 0.14, x1 = W * 0.80;
var topY = baseY - (x1 - x0) * Math.tan(th);
if (topY < H * 0.16) { topY = H * 0.16; x1 = x0 + (baseY - topY) / Math.tan(th); }

// ground
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(8, baseY); ctx.lineTo(W - 8, baseY); ctx.stroke();

// wedge: slope rises to the left, wedge pushed to the left
ctx.strokeStyle = C.rule; ctx.lineWidth = 2; ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(x0, topY); ctx.lineTo(x1, baseY); ctx.lineTo(x0, baseY); ctx.closePath();
ctx.fill(); ctx.stroke();

// angle label at the base of the slope
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", x1 - 46, baseY - 8);

// block sitting on the face
var fx = x0 + (x1 - x0) * 0.42, fy = topY + (baseY - topY) * 0.42;
var nx = -Math.sin(th), ny = -Math.cos(th);
var bx = fx + nx * 13, by = fy + ny * 13;
ctx.save();
ctx.translate(bx, by); ctx.rotate(-th);
ctx.fillStyle = C.figure; ctx.fillRect(-16, -13, 32, 26);
ctx.restore();

function arrow(x0a, y0a, dx, dy, col, lab, lx, ly) {
  var xe = x0a + dx, ye = y0a + dy;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0a, y0a); ctx.lineTo(xe, ye); ctx.stroke();
  var an = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(xe, ye);
  ctx.lineTo(xe - 9 * Math.cos(an - 0.4), ye - 9 * Math.sin(an - 0.4));
  ctx.lineTo(xe - 9 * Math.cos(an + 0.4), ye - 9 * Math.sin(an + 0.4));
  ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(lab, xe + lx, ye + ly);
}

var S = H * 0.019;
arrow(bx, by, 0, g * S, C.figure, "mg", 6, 12);
arrow(bx, by, nx * g * Math.cos(th) * S, ny * g * Math.cos(th) * S, C.ink, "N", -16, -6);
arrow(bx, by, p.a * S, 0, C.accent, "ma (pseudo)", 4, -6);

// slope direction guide
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]); ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(bx - 60 * Math.cos(th), by + 60 * Math.sin(th));
ctx.lineTo(bx + 60 * Math.cos(th), by - 60 * Math.sin(th)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("slope axis", bx + 46 * Math.cos(th), by - 46 * Math.sin(th) - 8);

// arrow showing wedge acceleration (to the left, into the slope)
arrow(x0 + 70, baseY + 22, -50, 0, C.accent, "", 0, 0);
ctx.fillStyle = C.ink;
ctx.fillText("wedge accelerates this way", x0 + 78, baseY + 26);

var need = g * Math.tan(th);
var along = p.a * Math.cos(th) - g * Math.sin(th);
var verdict = Math.abs(along) < 0.05 ? "block stays put" : (along > 0 ? "block rides up the face" : "block slides down the face");
out.note = "a needed = g tan(theta) = " + need.toFixed(3) + " m/s^2; net along slope = " + along.toFixed(2) + " m/s^2 -> " + verdict;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var R = p.R, Hd = p.depth, w = p.omega;
var rise = w * w * R * R / (2 * g);
var zc = Hd - rise / 2;
var dry = 0;
if (zc < 0) {
  var r2 = R * R - 2 * R * Math.sqrt(g * Hd) / (w > 0.001 ? w : 0.001);
  dry = r2 > 0 ? Math.sqrt(r2) : 0;
  zc = -w * w * dry * dry / (2 * g);
}
var zTop = zc + rise;
var view = Math.max(zTop * 1.25, Hd * 1.9, 0.04);

var left = W * 0.20, right = W * 0.80, floor = H * 0.82, ceil = H * 0.12;
var sx = (right - left) / (2 * R);
var sy = (floor - ceil) / view;
function px(r) { return left + (r + R) * sx; }
function py(z) { return floor - z * sy; }

// cylinder walls and floor
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(left, ceil); ctx.lineTo(left, floor); ctx.lineTo(right, floor); ctx.lineTo(right, ceil);
ctx.stroke();

// rest level for comparison
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 5]); ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, py(Hd)); ctx.lineTo(right, py(Hd)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("level at rest", left + 6, py(Hd) - 6);

// water body
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(left, floor);
for (var i = 0; i <= 120; i++) {
  var r = -R + 2 * R * i / 120;
  var z = zc + w * w * r * r / (2 * g);
  if (z < 0) z = 0;
  ctx.lineTo(px(r), py(z));
}
ctx.lineTo(right, floor);
ctx.closePath(); ctx.fill();

// surface curve
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 120; j++) {
  var r2b = -R + 2 * R * j / 120;
  var z2 = zc + w * w * r2b * r2b / (2 * g);
  if (z2 < 0) z2 = 0;
  if (j === 0) ctx.moveTo(px(r2b), py(z2)); else ctx.lineTo(px(r2b), py(z2));
}
ctx.stroke();

// axis of rotation
ctx.strokeStyle = C.figure; ctx.setLineDash([2, 4]); ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(px(0), ceil); ctx.lineTo(px(0), floor + 12); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("axis", px(0) + 4, ceil + 12);

// dry patch marker
if (dry > 0) {
  ctx.strokeStyle = C.accent; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(px(-dry), floor); ctx.lineTo(px(dry), floor); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText("dry bottom", px(0) - 32, floor + 18);
}

// rotation indicator, animated
var spin = w * t;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(px(0), ceil + 26, 14, spin, spin + 4.2); ctx.stroke();

// labels
ctx.fillStyle = C.ink;
ctx.fillText("r = -R", left - 2, floor + 18);
ctx.fillText("r = +R", right - 36, floor + 18);
ctx.fillText("z", px(-R) - 14, ceil + 14);

out.note = "rise across the radius = " + rise.toFixed(4) + " m, centre height = " + zc.toFixed(4) + " m" + (dry > 0 ? ", dry patch radius = " + dry.toFixed(4) + " m" : "");
